def test_official_terry_fator_has_proven_time_ticket_and_no_screening_or_theatre():
    events = extract_tribe_events(SOURCE_HTML)
    assert len(events) == 1
    event = events[0]
    assert event.title == "TERRY FATOR: A VERY TERRY CHRISTMAS"
    assert event.start_date == "2026-12-15T19:30:00-06:00"
    assert "/ticket/p/76154107/" in event.ticket_url
    assert event.event_url == "https://desplainestheatre.com/event/terry-fator-christmas-show/"
    assert event.ticket_price is None


@pytest.mark.parametrize(
    "old,new",
    [
        ("2026-12-15T19:30:00-06:00", "2026-12-15"),
        ("2026-12-15T19:30:00-06:00", "2026-12-15T19:30:00"),
        ("2026-12-15T19:30:00-06:00", "2026-12-15T20:30:00-06:00"),
        ("https://www.etix.com/ticket/p/76154107/", "https://untrusted.example/ticket/p/76154107/"),
        ("December 15 @ 7:30 pm", "December 15"),
    ],
)
def test_missing_or_conflicting_evidence_fails_instead_of_inventing(old, new):
    with pytest.raises(ValueError):
        extract_tribe_events(SOURCE_HTML.replace(old, new))


def test_unknown_html_is_not_a_verified_empty_calendar():
    with pytest.raises(ValueError):
        extract_tribe_events("<html>captcha</html>")


def test_pagination_requires_another_fetch_before_accepting_inventory():
    with pytest.raises(ValueError):
        extract_tribe_events(SOURCE_HTML + '<a class="tribe-events-c-nav__next" href="/events/page/2/">Next Events</a>')
